INSERT INTO policies (id, title, description, status, effective_date, published_at, notes) VALUES
  ('22222222-0000-0000-0000-000000000001', 'اشتراطات الترخيص السياحي للمنشآت', 'الاشتراطات الجديدة لترخيص المنشآت السياحية والمطاعم السياحية', 'published', '2026-10-01', now(), 'تحديث شامل لاشتراطات الترخيص السياحي'),
