INSERT INTO policy_clauses (id, policy_id, clause_number, old_text, new_text, summary) VALUES
  ('33333333-0000-0000-0000-000000000001', '22222222-0000-0000-0000-000000000001', '1', 'يجب أن تكون مساحة المطعم السياحي لا تقل عن 100 متر مربع.', 'يجب أن تكون مساحة المطعم السياحي لا تقل عن 60 متر مربع، مع توفير منطقة جلوس خارجية اختيارية.', 'تخفيض الحد الأدنى للمساحة من 100 إلى 60 متر مربع'),
  ('33333333-0000-0000-0000-000000000002', '22222222-0000-0000-0000-000000000001', '2', 'يلزم الحصول على تصنيف سياحي من وزارة السياحة قبل التشغيل.', 'يلزم الحصول على تصنيف سياحي من وزارة السياحة، أو تسجيل ذاتي عبر بوابة السياحة الإلكترونية.', 'إضافة خيار التسجيل الذاتي كبديل للتصنيف'),
  ('33333333-0000-0000-0000-000000000003', '22222222-0000-0000-0000-000000000002', '1', 'تلتزم المنشآت التجارية بتقديم إقرار الزكاة سنويًا.', 'تلتزم المنشآت التجارية بتقديم إقرار الزكاة سنويًا، والتسجيل في نظام فاتورة الإلكتروني للفوترة الضريبية.', 'إضافة التزام التسجيل في نظام فاتورة'),
  ('33333333-0000-0000-0000-000000000004', '22222222-0000-0000-0000-000000000003', '1', 'يلزم توفير شهادة سلامة مهنية للعاملين في القطاع السياحي.', 'يلزم توفير شهادة سلامة مهنية معتمدة من وزارة الموارد البشرية للعاملين في القطاع السياحي والضيافة، مع تجديدها كل سنتين.', 'إضافة شرط تجديد الشهادة كل سنتين')
