INSERT INTO tasks (id, policy_id, service_id, from_agency_id, to_agency_id, title, description, reason, status, created_at, started_at, completed_at) VALUES
  ('55555555-0000-0000-0000-000000000001', '22222222-0000-0000-0000-000000000001', '44444444-0000-0000-0000-000000000003', '11111111-0000-0000-0000-000000000005', '11111111-0000-0000-0000-000000000002', 'تحديث اشتراطات رخص البناء للمنشآت السياحية', 'بناءً على تحديث سياسة الترخيص السياحي، يلزم تحديث إجراءات رخص البناء للمنشآت السياحية لتتوافق مع الحد الأدنى الجديد للمساحة (60 متر مربع).', 'الجهة المسؤولة عن ترخيص البناء', 'new', now() - interval '2 days', null, null),
  ('55555555-0000-0000-0000-000000000002', '22222222-0000-0000-0000-000000000002', '44444444-0000-0000-0000-000000000008', '11111111-0000-0000-0000-000000000004', '11111111-0000-0000-0000-000000000001', 'تحديث إجراءات التسجيل في نظام فاتورة للمستثمرين', 'بناءً على تحديث لوائح التزام المنشآت، يلزم تحديث إجراءات التسجيل في نظام فاتورة للمستثمرين الجدد.', 'الجهة المسؤولة عن نظام فاتورة', 'new', now() - interval '1 day', null, null),
  ('55555555-0000-0000-0000-000000000003', '22222222-0000-0000-0000-000000000003', '44444444-0000-0000-0000-000000000005', '11111111-0000-0000-0000-000000000005', '11111111-0000-0000-0000-000000000003', 'تحديث متطلبات شهادة السلامة المهنية للعاملين في السياحة', 'بناءً على تحديث اشتراطات السلامة المهنية، يلزم تحديث متطلبات إصدار شهادة السلامة المهنية لتشمل شرط التجديد كل سنتين.', 'الجهة المسؤولة عن شهادات السلامة المهنية', 'new', now() - interval '3 hours', null, null),
  ('55555555-0000-0000-0000-000000000004', '22222222-0000-0000-0000-000000000001', '44444444-0000-0000-0000-000000000009', '11111111-0000-0000-0000-000000000002', '11111111-0000-0000-0000-000000000005', 'تحديث نماذج الترخيص السياحي للمنشآت', 'تحديث نماذج الترخيص السياحي لتعكس الحد الأدنى الجديد للمساحة وخيار التسجيل الذاتي.', 'الجهة المسؤولة عن الترخيص السياحي', 'in_progress', now() - interval '5 days', now() - interval '3 days', null),
  ('55555555-0000-0000-0000-000000000005', '22222222-0000-0000-0000-000000000002', '44444444-0000-0000-0000-000000000007', '11111111-0000-0000-0000-000000000004', '11111111-0000-0000-0000-000000000001', 'تحديث دليل التسجيل في ضريبة القيمة المضافة للمستثمرين', 'تحديث الدليل الإرشادي للتسجيل في ضريبة القيمة المضافة ليشمل المتطلبات الجديدة لنظام فاتورة.', 'الجهة المسؤولة عن الضرائب', 'in_progress', now() - interval '4 days', now() - interval '2 days', null),
  ('55555555-0000-0000-0000-000000000006', '22222222-0000-0000-0000-000000000001', '44444444-0000-0000-0000-000000000004', '11111111-0000-0000-0000-000000000005', '11111111-0000-0000-0000-000000000002', 'تحديث اشتراطات تشغيل الإسكان السياحي المفروش', 'تحديث اشتراطات تشغيل وحدات الإسكان السياحي المفروش لتتوافق مع التحديثات الجديدة.', 'الجهة المسؤولة عن تراخيص الإسكان', 'in_progress', now() - interval '6 days', now() - interval '4 days', null),
  ('55555555-0000-0000-0000-000000000007', '22222222-0000-0000-0000-000000000003', '44444444-0000-0000-0000-000000000006', '11111111-0000-0000-0000-000000000005', '11111111-0000-0000-0000-000000000003', 'تحديث مناهج تدريب العاملين في الضيافة', 'تحديث مناهج التدريب لتشمل متطلبات السلامة المهنية الجديدة للعاملين في الضيافة.', 'الجهة المسؤولة عن تدريب العاملين', 'evidence_sent', now() - interval '8 days', now() - interval '6 days', null),
  ('55555555-0000-0000-0000-000000000008', '22222222-0000-0000-0000-000000000001', '44444444-0000-0000-0000-000000000010', '11111111-0000-0000-0000-000000000002', '11111111-0000-0000-0000-000000000005', 'تحديث معايير تصنيف المنشآت السياحية', 'تحديث معايير التصنيف لتعكس الحد الأدنى الجديد للمساحات.', 'الجهة المسؤولة عن التصنيف السياحي', 'evidence_sent', now() - interval '7 days', now() - interval '5 days', null),
  ('55555555-0000-0000-0000-000000000009', '22222222-0000-0000-0000-000000000002', '44444444-0000-0000-0000-000000000008', '11111111-0000-0000-0000-000000000004', '11111111-0000-0000-0000-000000000005', 'ربط نظام فاتورة ببوابة السياحة الإلكترونية', 'ربط نظام الفوترة الإلكترونية ببوابة وزارة السياحة لإصدار فواتير تلقائية للمنشآت السياحية.', 'الجهة المسؤولة عن نظام فاتورة', 'needs_completion', now() - interval '10 days', now() - interval '8 days', null),
  ('55555555-0000-0000-0000-000000000010', '22222222-0000-0000-0000-000000000001', '44444444-0000-0000-0000-000000000001', '11111111-0000-0000-0000-000000000005', '11111111-0000-0000-0000-000000000001', 'تحديث دليل المستثمر للقطاع السياحي', 'تحديث الدليل الإرشادي للمستثمرين في القطاع السياحي ليشمل التسهيلات الجديدة.', 'الجهة المسؤولة عن تراخيص الاستثمار', 'completed', now() - interval '12 days', now() - interval '10 days', now() - interval '5 days'),
  ('55555555-0000-0000-0000-000000000011', '22222222-0000-0000-0000-000000000003', '44444444-0000-0000-0000-000000000011', '11111111-0000-0000-0000-000000000003', '11111111-0000-0000-0000-000000000005', 'تحديث متطلبات تصريح المرشد السياحي', 'تحديث متطلبات تصريح المرشد السياحي لتشمل شرط السلامة المهنية الجديد.', 'الجهة المسؤولة عن تصاريح المرشدين', 'completed', now() - interval '15 days', now() - interval '13 days', now() - interval '9 days'),
  ('55555555-0000-0000-0000-000000000012', '22222222-0000-0000-0000-000000000001', '44444444-0000-0000-0000-000000000003', '11111111-0000-0000-0000-000000000005', '11111111-0000-0000-0000-000000000002', 'تحديث نماذج رخص البناء للمنشآت السياحية', 'تحديث نماذج رخص البناء لتعكس الحد الأدنى الجديد للمساحة.', 'الجهة المسؤولة عن رخص البناء', 'completed', now() - interval '20 days', now() - interval '18 days', now() - interval '12 days')
INSERT INTO evidence (id, task_id, agency_id, summary, file_url, file_name, file_type, status, reviewer_note, submitted_at, reviewed_at) VALUES
  ('66666666-0000-0000-0000-000000000001', '55555555-0000-0000-0000-000000000007', '11111111-0000-0000-0000-000000000003', 'تم تحديث مناهج التدريب لتشمل وحدة السلامة المهنية الجديدة مدتها 8 ساعات، مع اختبار قبول وآخر ختامي. تم اعتماد المناهج من لجنة المختصين.', 'https://hrsd.gov.sa/training/curriculum-updated.pdf', 'curriculum-updated.pdf', 'pdf', 'submitted', null, now() - interval '3 days', null),
  ('66666666-0000-0000-0000-000000000002', '55555555-0000-0000-0000-000000000008', '11111111-0000-0000-0000-000000000005', 'تم تحديث معايير التصنيف لتشمل 4 درجات بناءً على المساحة والخدمات. أُرفق تقرير المعايير المحدّث.', 'https://mt.gov.sa/classification-standards.pdf', 'classification-standards.pdf', 'pdf', 'submitted', null, now() - interval '2 days', null),
  ('66666666-0000-0000-0000-000000000003', '55555555-0000-0000-0000-000000000010', '11111111-0000-0000-0000-000000000001', 'تم تحديث دليل المستثمر ليشمل فصلًا جديدًا عن التسهيلات السياحية وخيار التسجيل الذاتي. الدليل متاح على بوابة الاستثمار.', 'https://investsaudi.sa/guide-tourism-v2.pdf', 'guide-tourism-v2.pdf', 'pdf', 'approved', 'دليل شامل وواضح، اعتمد للنشر', now() - interval '6 days', now() - interval '5 days'),
  ('66666666-0000-0000-0000-000000000004', '55555555-0000-0000-0000-000000000009', '11111111-0000-0000-0000-000000000005', 'تم ربط نظام فاتورة ببوابة السياحة لكن يفتقد لتكامل واجهة الفوترة التلقائية.', 'https://mt.gov.sa/integration-status.pdf', 'integration-status.pdf', 'pdf', 'rejected', 'التكامل غير مكتمل — واجهة الفوترة التلقائية لا تعمل. يرجى استكمال الربط وإعادة الرفع.', now() - interval '5 days', now() - interval '4 days'),
  ('66666666-0000-0000-0000-000000000005', '55555555-0000-0000-0000-000000000011', '11111111-0000-0000-0000-000000000005', 'تم تحديث متطلبات تصريح المرشد السياحي لتشمل شرط شهادة السلامة المهنية مع التجديد كل سنتين. أُرفق القرار المحدّث.', 'https://mt.gov.sa/guide-permit-update.pdf', 'guide-permit-update.pdf', 'pdf', 'approved', 'تم اعتماد التحديث، شكرًا للجهود', now() - interval '10 days', now() - interval '9 days')
